"""Build a local, self-contained motion player referencing native PNGs."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
ART=ROOT/'Planning/Story/Monster-v86/outskirts'
jobs=json.loads((ART/'jobs.json').read_text(encoding='utf-8'))
qa=json.loads((ART/'review-decisions.json').read_text(encoding='utf-8'))
data=[]
for row in jobs['jobs']:
    key=row['id'];item={k:row[k] for k in ('id','name','stage','height','facesRight')}
    from PIL import Image
    b=Image.open(ART/key/'animation-input.png').getbbox()
    item['referenceHeight']=b[3]-b[1];item['motions']={}
    for motion in ('idle','attack','stun'):
        decision=qa[key][motion]
        item['motions'][motion]={**decision,'frames':[f'{key}/{row.get(motion+"Dir",motion)}/{i:02}.png' for i in decision['sourceFrames']]}
    item['motions']['hit']={'frames':[f'{key}/animation-input.png'],'holdsMs':[900],'sourceFrames':[0]}
    data.append(item)
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>성 밖 몬스터 · v8.6 모션 검수</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0d1824;color:#dbe6de;font:15px/1.7 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:28px}h1{font-size:26px;color:#f9d296;margin:0 0 5px}p{margin:8px 0}button{font:inherit;color:#f9d296;border:1px solid #58747b;background:#17303d;padding:7px 18px;cursor:pointer;border-radius:4px}button.active{background:#f4a00f;color:#061322}nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}label{margin-left:auto;align-self:center}a{color:#f9d296}#cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#142533;border:1px solid #34505b;padding:14px;border-radius:6px}h2{font-size:20px;color:#f9d296;margin:0}.meta{font-size:12px;color:#8fa7a2}canvas{width:100%;height:auto;image-rendering:pixelated;background:#1b2d3d;display:block;margin:12px 0}.progress{height:4px;background:#34505b}.fill{height:100%;background:#f4a00f}.status{font-size:13px;color:#f9d296;min-height:23px}.links{display:flex;gap:12px;flex-wrap:wrap;font-size:13px}.note{background:#142533;padding:18px;margin-top:18px;border-left:3px solid #f4a00f;font-size:14px}.wide{width:100%;image-rendering:pixelated;border:1px solid #34505b;margin-top:12px}details{margin-top:18px}summary{cursor:pointer;color:#f9d296}@media(max-width:850px){#cards{grid-template-columns:1fr}main{padding:16px}label{margin-left:0}}
</style><main><h1>성 밖 몬스터 · v8.6</h1><p>4~9스테이지를 여우·멧돼지·오소리·스라소니·산양·큰 사슴으로 구분합니다. 원본 주인공과 기존 동물의 굵은 윤곽선, 작은 눈, 단순한 명암을 유지하며 꼬리·엄니·얼굴 무늬·귀털·뿔로 각자의 특징을 표현했습니다.</p>
<nav id="modes"><button data-mode="idle" class="active">대기</button><button data-mode="attack">공격</button><button data-mode="stun">기절</button><button data-mode="hit">피격 · 흰색 점멸</button><button id="pause">일시 정지</button><label><input id="contact" type="checkbox"> 접촉점 표시</label></nav>
<div id="cards"></div><div class="note">대기는 발을 고정한 작은 호흡입니다. 피격은 기본 이미지가 잠깐 하얗게 변한 뒤 돌아옵니다. 기절은 힘이 빠진 자세를 유지합니다. 사망 모션은 없습니다.<br>원본 주인공 이미지는 수정하지 않았습니다. 이 페이지의 모든 모션은 PixelLab 원본 프레임이며, 코드로 만든 관절 이동·회전·변형은 사용하지 않았습니다.</div>
<details><summary>실게임 크기 · 전체 프레임 검수</summary><p>화면 높이 540px / 카메라 월드 높이 6.2 기준. 왼쪽은 원본 주인공, 오른쪽은 실제 크기와 방향의 몬스터입니다. 공격 위치는 별도 게임 런타임이 접촉점에 맞추므로, 아래 플레이어는 모션 크기 비교를 위한 고정 배치입니다.</p><img class="wide" src="selected-bases-game-scale.png"><p>원본 프레임을 하나씩 확인해 발 들림·잘림·몸통 변형이 없는 구간만 선택했습니다. 대기는 접지를 유지하고 공격은 준비→접촉→복귀가 읽히도록 구성했습니다. 생성 이력과 선택 사유는 jobs.json 및 review-decisions.json에 남겨 두었습니다.</p></details>
<p class="meta">입력·생성 이력: <a href="jobs.json">jobs.json</a> · <a href="review-decisions.json">검수 결과</a> · <a href="manifest-fragment.json">통합 데이터</a></p></main>
<script>const data=__DATA__;const hero=new Image();hero.src='../../../../Client/Assets/Game/Art/Presentation/Clips/hero-v5-idle/01.png';let mode='idle',start=performance.now(),paused=false,pausedAt=0;const labels={idle:'대기',attack:'공격',stun:'기절',hit:'피격'};let views=[];
for(const row of data){for(const clip of Object.values(row.motions))clip.images=clip.frames.map(src=>{const im=new Image();im.src=src;return im});const el=document.createElement('section');el.className='card';el.innerHTML=`<h2>${row.name}</h2><div class="meta">${row.id} · 체형 높이 ${row.height} · 기준 ${row.referenceHeight}px</div><canvas width="600" height="310"></canvas><div class="progress"><div class="fill"></div></div><div class="status"></div><div class="links"><a href="${row.id}-idle-selected.png">대기 전 프레임</a><a href="${row.id}-attack-selected.png">공격 전 프레임</a><a href="${row.id}-stun-selected.png">기절 전 프레임</a></div>`;document.querySelector('#cards').append(el);views.push({row,el,canvas:el.querySelector('canvas'),ctx:el.querySelector('canvas').getContext('2d'),buf:document.createElement('canvas')})}
function sprite(ctx,img,x,y,s,flip=false,flash=false){if(!img.complete||!img.naturalWidth)return;ctx.save();ctx.translate(x,y);ctx.scale(flip?-s:s,s);ctx.drawImage(img,-64,-80);ctx.restore()}
function paint(now){const clock=paused?pausedAt:now;for(const v of views){const {row,ctx,canvas}=v;const clip=row.motions[mode];const duration=clip.holdsMs.reduce((a,b)=>a+b,0),period=duration+(mode==='attack'?550:0);const elapsed=(clock-start)%period;let frame=0,total=0;for(let i=0;i<clip.holdsMs.length;i++){total+=clip.holdsMs[i];frame=i;if(elapsed<total)break}const resting=mode==='attack'&&elapsed>=duration;const img=resting?row.motions.idle.images[0]:clip.images[frame];ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,600,310);ctx.fillStyle='#20343d';ctx.fillRect(0,254,600,3);const scale=row.height*540/6.2/row.referenceHeight;const heroScale=1.1*540/6.2/84;if(hero.complete){ctx.drawImage(hero,100-64*heroScale,254-114*heroScale,128*heroScale,128*heroScale)}let drawImage=img;if(mode==='hit'&&elapsed<130&&img.complete){v.buf.width=128;v.buf.height=96;const c=v.buf.getContext('2d');c.drawImage(img,0,0);c.globalCompositeOperation='source-in';c.fillStyle='#ffffff';c.fillRect(0,0,128,96);drawImage=v.buf}sprite(ctx,drawImage,430,254,scale,row.facesRight);ctx.font='14px system-ui';ctx.fillStyle='#8fa7a2';ctx.fillText('원본 주인공',52,284);ctx.fillText(row.name,397,284);const contact=!resting&&mode==='attack'&&frame===clip.contactFrame;if(document.querySelector('#contact').checked&&mode==='attack'){const p=clip.contactPoint;const cx=430+(row.facesRight?-1:1)*(p.x-64)*scale,cy=254+(p.y-80)*scale;ctx.strokeStyle=contact?'#f4a00f':'#58747b';ctx.beginPath();ctx.moveTo(cx-7,cy);ctx.lineTo(cx+7,cy);ctx.moveTo(cx,cy-7);ctx.lineTo(cx,cy+7);ctx.stroke()}v.el.querySelector('.fill').style.width=`${Math.min(elapsed/duration,1)*100}%`;v.el.querySelector('.status').textContent=resting?'공격 후 복귀':`${labels[mode]} · ${frame+1}/${clip.images.length} 프레임${contact?' · 접촉!':''}${mode==='attack'?` · 접촉 ${clip.contactTimeMs}ms / 전체 ${duration}ms`:''}`;}requestAnimationFrame(paint)}requestAnimationFrame(paint);
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;start=performance.now();pausedAt=start;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b))});document.querySelector('#pause').onclick=e=>{if(paused){start+=performance.now()-pausedAt;paused=false;e.target.textContent='일시 정지'}else{pausedAt=performance.now();paused=true;e.target.textContent='재생'}};
</script></html>'''
(ART/'preview.html').write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False)),encoding='utf-8')
print('Created UTF-8 native-frame preview.')
